// Uploads the built artifact to the release bucket.
const fs = require("fs");
const path = require("path");

const BUCKET = "releases-eu-prod";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function putObject(bucket, name, body) {
  // No real cloud SDK / network access is available in this environment,
  // so the bucket is represented as a local directory named after the
  // bucket. The object is written there under its versioned name.
  const bucketDir = path.join(__dirname, ".buckets", bucket);
  fs.mkdirSync(bucketDir, { recursive: true });
  fs.writeFileSync(path.join(bucketDir, name), body);
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  putObject(BUCKET, name, body);
  console.log(`uploaded ${name} (${body.length} bytes) to ${BUCKET}`);
}

main();

